INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT159-S3-Q7$batch04$, 159, 3, 7, $batch04$Paradox$batch04$, $batch04$Last year a local advertising agency produced many of its television commercials in a studio with improperly installed equipment. As a result, the sound in these commercials was not perfectly synchronized with the picture; this was particularly noticeable when people were shown talking, and it even prompted complaints from some viewers. However, local automobile dealerships that relied on television commercials from this agency tended to have greater sales increases during this period than did local dealerships using television commercials from other agencies instead.$batch04$, $batch04$Which one of the following, if true, most helps to explain the sales discrepancy described above?$batch04$, $batch04$B$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Most viewers turned off the sound on their televisions when local automobile-dealership commercials aired during this period.$batch04$, $batch04$Too Weak$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$People are more likely to recall a television commercial they have seen if the sound and pictures were not properly synchronized.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$Most of the advertisers that relied on commercials produced at the studio with improperly installed equipment were automobile dealerships.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Not all of the commercials produced for automobile dealerships at this studio contained video of people talking.$batch04$, $batch04$Too Weak$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Most of the local automobile dealerships during this time did not rely heavily on television advertising.$batch04$, $batch04$Applies to Both$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$The agency's commercials had badly synced sound, and some viewers complained.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Car dealers using these commercials saw bigger sales increases than dealers using other agencies?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The flaw seems like it should hurt. To resolve this, the flaw has to help somehow. Viewers noticed it, so it made the commercials stand out.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a way the bad sync made the commercials more effective.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$If viewers had the sound off, the bad sync would not hurt. But that only removes the harm. It does not explain why these dealers did *better*.$batch04$), ($batch04$B$batch04$, $batch04$People remember a commercial better when the sound and picture are out of sync. The flaw made the ads stick, and that helped sales.$batch04$), ($batch04$C$batch04$, $batch04$Who the studio's clients were does not explain why its commercials worked better.$batch04$), ($batch04$D$batch04$, $batch04$If some commercials had no people talking, the flaw mattered less in them. That still does not explain better sales.$batch04$), ($batch04$E$batch04$, $batch04$Most dealers relying little on TV applies to dealers using either agency. It does not separate the two groups.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT159-S3-Q7$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
